import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";
import { createBuilder } from "../src/builder";
import type { OutlinePoint } from "../src/builder";
import type { Fill } from "../src/context";
import { limb } from "../src/ik";
import { rng } from "../src/math";
import { catmull, polyline, spiral } from "../src/path";
import type { PartOptions } from "../src/parts";
import { gradient, grain, mottle, paint, stripes } from "../src/paint";
import type { StickOptions } from "../src/surface";
import { svg } from "../src/texture";
import { glow } from "../kits/glow";

export const meta = {
  name: "Gnome Tinkerer",
  description:
    "A knee-high gnome inventor with a floppy goggled hat, a snowy beard and a huge leather backpack bristling with gadgets: spinning propeller, spyglass, antenna coil, pressure gauge, cogs, wrench, lantern and kettle.",
  style: "whimsical low-poly mix",
  commit: "88fc1f0",
};

// ---------------------------------------------------------------------------------------------------------------
// Palette
const SKIN = "#f2b48f";
const SKIN_D = "#d98f6e";
const NOSE = "#ee8478";
const BLUSH = "#f0766f";
const WHITE = "#fffaf0";
const DARK = "#2b2230";
const MOUTH = "#8c2f3c";
const BEARD = "#f4eee0";
const BEARD_S = "#d9d4cd";
const HAT = "#d8453a";
const HAT_D = "#a92f36";
const TUNIC = "#e6a938";
const TUNIC_D = "#c58422";
const TEAL = "#2f8f9d";
const TEAL_D = "#22707c";
const OLIVE = "#7d9250";
const OLIVE_D = "#617637";
const BOOT = "#7a4a2c";
const BOOT_D = "#4f2f1c";
const BOOT_L = "#a3693d";
const CREAM = "#f6e7c1";
const LEATHER = "#a56a38";
const LEATHER_D = "#7a4723";
const LEATHER_L = "#c28a50";
const BRASS = "#e0aa3e";
const BRASS_D = "#b57e24";
const COPPER = "#d2733e";
const STEEL = "#8d99a6";
const STEEL_D = "#5d6874";
const GLASS = "#8be8ff";
const AMBER = "#ffc65a";
const RED = "#e0463c";
const PENCIL = "#f2cf3a";

type Pts = number[][];

const sph = (r: number, w = 7, h = 5) => new THREE.SphereGeometry(r, w, h);
const cyl = (rt: number, rb: number, h: number, seg = 8) => new THREE.CylinderGeometry(rt, rb, h, seg);
const box = (w: number, h: number, d: number) => new THREE.BoxGeometry(w, h, d);

const unitV = (v: THREE.Vector3) => v.clone().normalize();
const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
const add = (p: number[], d: THREE.Vector3 | number[], k = 1) => [
  p[0] + (Array.isArray(d) ? d[0] : d.x) * k,
  p[1] + (Array.isArray(d) ? d[1] : d.y) * k,
  p[2] + (Array.isArray(d) ? d[2] : d.z) * k,
];

/** Piecewise-linear interpolation through [t, value] keys. */
function pl(keys: number[][], t: number) {
  if (t <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) {
    if (t <= keys[i][0]) {
      const f = (t - keys[i - 1][0]) / (keys[i][0] - keys[i - 1][0]);
      return keys[i - 1][1] + (keys[i][1] - keys[i - 1][1]) * f;
    }
  }
  return keys[keys.length - 1][1];
}

function gearOutline(teeth: number, ro: number, ri: number): OutlinePoint[] {
  const out: OutlinePoint[] = [];
  const w = (Math.PI * 2) / teeth;
  for (let i = 0; i < teeth; i++) {
    const a = i * w;
    for (const [da, r] of [
      [-0.3, ri],
      [-0.16, ro],
      [0.16, ro],
      [0.3, ri],
    ]) {
      out.push([Math.cos(a + da * w) * r, Math.sin(a + da * w) * r]);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Drawings
const gaugeSvg = () => {
  let ticks = "";
  for (let i = 0; i <= 10; i++) {
    const a = ((-215 + i * 25) * Math.PI) / 180;
    const r0 = i % 5 === 0 ? 30 : 34;
    ticks += `<line x1="${50 + Math.cos(a) * r0}" y1="${50 + Math.sin(a) * r0}" x2="${50 + Math.cos(a) * 40}" y2="${50 + Math.sin(a) * 40}" stroke="#2b2230" stroke-width="3"/>`;
  }
  const na = (-215 + 6.4 * 25) * (Math.PI / 180);
  return svg(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="49" fill="#f7efd8"/>
<path d="M50 50 L${50 + Math.cos((-215 * Math.PI) / 180) * 44} ${50 + Math.sin((-215 * Math.PI) / 180) * 44} A44 44 0 0 1 ${50 + Math.cos((-95 * Math.PI) / 180) * 44} ${50 + Math.sin((-95 * Math.PI) / 180) * 44} Z" fill="#8fd18a"/>
<path d="M50 50 L${50 + Math.cos((-95 * Math.PI) / 180) * 44} ${50 + Math.sin((-95 * Math.PI) / 180) * 44} A44 44 0 0 1 ${50 + Math.cos((-45 * Math.PI) / 180) * 44} ${50 + Math.sin((-45 * Math.PI) / 180) * 44} Z" fill="#f4cf55"/>
<path d="M50 50 L${50 + Math.cos((-45 * Math.PI) / 180) * 44} ${50 + Math.sin((-45 * Math.PI) / 180) * 44} A44 44 0 0 1 ${50 + Math.cos((35 * Math.PI) / 180) * 44} ${50 + Math.sin((35 * Math.PI) / 180) * 44} Z" fill="#e8584c"/>
<circle cx="50" cy="50" r="30" fill="#f7efd8"/>${ticks}
<line x1="50" y1="50" x2="${50 + Math.cos(na) * 34}" y2="${50 + Math.sin(na) * 34}" stroke="#c0392b" stroke-width="4"/>
<circle cx="50" cy="50" r="6" fill="#2b2230"/></svg>`,
    { size: 128 },
  );
};

const patchSvg = svg(
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect x="1" y="1" width="38" height="38" rx="5" fill="#2f8f9d"/>
<rect x="4" y="4" width="32" height="32" rx="3" fill="none" stroke="#f6e7c1" stroke-width="2" stroke-dasharray="4 3"/>
<polygon points="20,9 23.5,16.5 31.5,17.5 25.5,23 27.5,31 20,27 12.5,31 14.5,23 8.5,17.5 16.5,16.5" fill="#f6e7c1"/></svg>`,
  { size: 128 },
);

const badgeSvg = (() => {
  let cog = "";
  for (let i = 0; i < 8; i++) {
    const a = (i * 45 * Math.PI) / 180;
    cog += `<rect x="-3" y="-17" width="6" height="7" fill="#2b2230" transform="translate(32 32) rotate(${i * 45})"/>`;
    void a;
  }
  return svg(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><circle cx="32" cy="32" r="30" fill="#e0aa3e"/><circle cx="32" cy="32" r="26" fill="#f6e7c1"/>
${cog}<circle cx="32" cy="32" r="12" fill="#2b2230"/><circle cx="32" cy="32" r="5" fill="#f6e7c1"/>
<rect x="29" y="8" width="6" height="48" rx="3" fill="#d8453a" transform="rotate(45 32 32)" opacity="0.0"/></svg>`,
    { size: 128 },
  );
})();

const swirlSvg = svg(
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><circle cx="32" cy="32" r="31" fill="#f6e7c1"/>
<path d="M32 32 m0 -3 a3 3 0 1 1 -3 3 a7 7 0 1 1 7 7 a11 11 0 1 1 -11 -11 a15 15 0 1 1 15 15 a19 19 0 1 1 -19 -19 a23 23 0 1 1 23 23" fill="none" stroke="#2f8f9d" stroke-width="3"/></svg>`,
  { size: 128 },
);

const tagSvg = svg(
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 32"><rect x="1" y="1" width="46" height="30" rx="4" fill="#f6e7c1" stroke="#7a4723" stroke-width="2"/>
<path d="M8 22 L14 10 L20 22 M10.5 18 H17.5" stroke="#d8453a" stroke-width="3" fill="none"/>
<path d="M26 12 H40 M26 18 H38 M26 24 H34" stroke="#7a4723" stroke-width="2.5"/></svg>`,
  { size: 128 },
);

export default function build() {
  const b = createBuilder({ name: "gnomeTinkerer" });
  const rand = rng(23);
  void rand;

  const P = (geo: THREE.BufferGeometry, color: Fill, opts: PartOptions = {}) => b.part(geo, color, { flat: true, ...opts });
  const S = (geo: THREE.BufferGeometry, color: Fill, on: Parameters<typeof b.stick>[2], opts: StickOptions = {}) =>
    b.stick(geo, color, on, { flat: true, ...opts });
  /** Many equal studs on one bone as one part. */
  const studs = (pts: Pts, r: number, color: Fill, bone: Parameters<typeof b.part>[2] extends infer O ? NonNullable<O> extends { bone?: infer B } ? B : never : never) =>
    P(
      mergeGeometries(pts.map((p) => sph(r, 5, 4).translate(p[0], p[1], p[2])))!,
      color,
      { bone, at: [0, 0, 0] },
    );

  // ------------------------------------------------------------------------------------------------------------
  // Skeleton
  const hips = b.joint("hips", { at: [0, 0.4, 0] });
  const spine = b.chain(
    "spine",
    catmull([
      [0, 0.4, 0],
      [0, 0.5, 0.01],
      [0, 0.62, 0],
      [0, 0.74, -0.01],
    ]),
    { parent: hips, names: ["spine1", "spine2", "chest"], role: "spine" },
  );
  const chest = spine.joints[2];
  const belly = spine.joints[1];
  const neck = b.joint("neck", { parent: chest, at: [0, 0.74, -0.01], aim: [0, 0.82, 0.01], role: "neck" });
  const head = b.joint("head", { parent: neck, at: [0, 0.82, 0.01], dir: [0, 1, 0.12], role: "head" });
  const jaw = b.joint("jaw", { parent: head, at: [0, 0.83, 0.07], aim: [0, 0.795, 0.17], role: "jaw" });

  // ------------------------------------------------------------------------------------------------------------
  // Torso, tunic, belt
  const tunicPaint = mottle(TUNIC, TUNIC_D, { size: 0.1, contrast: 0.7, seed: 4 });
  const bodyPaint = paint((p, n) => {
    const halfW = 0.085 + (0.66 - p.y) * 0.34;
    const dx = Math.abs(p.x);
    const inside = p.z > 0.02 && n.z > 0.1 && p.y < 0.665 && p.y > 0.4 && dx < halfW;
    if (inside) {
      const edge = Math.min(halfW - dx, p.y - 0.4, 0.665 - p.y);
      if (edge < 0.012) return LEATHER_D;
      if (edge < 0.022 && Math.floor(p.y / 0.014 + p.x / 0.014) % 2 === 0) return CREAM;
      return LEATHER;
    }
    if (p.y < 0.36) return OLIVE;
    return tunicPaint;
  });
  const torsoKeysX = [
    [0, 0.15],
    [0.3, 0.195],
    [0.65, 0.18],
    [0.9, 0.14],
    [1, 0.085],
  ];
  const torsoKeysZ = [
    [0, 0.15],
    [0.3, 0.185],
    [0.65, 0.16],
    [0.9, 0.12],
    [1, 0.08],
  ];
  const torso = b.sweep(spine, (t) => [pl(torsoKeysX, t), pl(torsoKeysZ, t)], {
    shift: (t) => [0, -0.03 * Math.sin(Math.PI * Math.min(t * 1.1, 1))],
    sides: 8,
    smooth: false,
    color: bodyPaint,
  });
  const skin = b.surface(torso);

  // flared tunic skirt with trim
  const skirtPaint = paint((p) => {
    if (p.y < 0.335) return Math.floor((p.x + p.z + 1) / 0.04) % 2 ? CREAM : TEAL;
    if (p.y < 0.35) return TEAL_D;
    return tunicPaint;
  });
  P(
    b.lathe(
      [
        [0.2, 0.0],
        [0.225, -0.012],
        [0.255, -0.15],
        [0.24, -0.155],
        [0.19, -0.125],
        [0.165, -0.03],
      ],
      { at: [0, 0.465, 0.0], bone: belly, segments: 8, color: skirtPaint },
    ).mesh.geometry,
    skirtPaint,
    { bone: belly, at: [0, 0, 0], visible: false } as PartOptions,
  );
  return b.root;
}

